fn sub_plan(&self, version, rnd, player, data, goal_data, _debug) -> SubPlan

// L29 — 내 챔피언
team = player.info.team                      // PlayerState+0x930, team>=2 면 panic_bounds_check
pos  = player.info.position.as_index()       // PlayerState+0x9c0, 0..5
champ: &Entity = data.cache.player_champion[team][pos].unwrap()   // cache+0x1e0, None 이면 unwrap_failed

// L31 — 내 HP 비율(정수 %)
if champ.stat_cached.hp == 0 { panic_const_div_by_zero }
hp_ratio = champ.hp * 100 / champ.stat_cached.hp        // +0x670, +0x628

// L32 — 살아있는 에픽 몬스터(있으면)
moba = (data.cache.game.__method8()).as_moba().unwrap()  // vtable+0x40 반환 {tag,ptr}; tag!=0 이면 unwrap_failed
epic: Option<&Entity> = moba.jungle_runner.epic.live_list.get(0)
                            .map(|e| data.cache.game.__method62(*e))   // vtable+0x1f0, id -> Option<&Entity>
// live_list 가 비면 epic = None

// L33 — 우리 팀 분수대 사각형
(lx, ly, rx, ry) = data.context.map.fountain(team)       // MapDef+0x6d70 + team*32, +0/+8/+0x10/+0x18

// L34 — 내가 분수대(회복지역) 안에 있는가
is_in_heal_area = (champ.x >= lx && champ.x <= rx) && (champ.y >= ly && champ.y <= ry)
// IR 상 x 범위가 먼저 판정되고, 참일 때만 y 범위를 계산해 phi 로 합침(false 로 단락)

// L35 — 아이템 업그레이드 가능?
can_upgrade_item = upgrade_item(version, rnd, player, data.cache.game, data.context).is_some()
// 반환 24B 의 +0x0 판별자(range 0..2) != 0 인지로 판단

// L36 — 귀환 판정
if epic.is_some_and(|e| e.hp == e.stat_cached.hp)         // 에픽이 '풀피' = 아직 아무도 안 팬 상태
   && ( hp_ratio < 51
        || can_upgrade_item
        || (champ.hp < champ.stat_cached.hp && is_in_heal_area) )
{
    return SubPlan::Recall(RecallSubPlan)   // tag 5. RecallSubPlan 은 ZST — 페이로드 스토어 없음
}
// epic 이 None 이거나 에픽이 이미 피가 깎여 있으면 이 블록 자체를 건너뜀

// L41~L43 — 부쉬 은신
if goal_data.epic.epic_ally_tick + data.context.setting.tick_per_second
       > goal_data.epic.epic_ally_killed_tick
   && self.target_bush.is_some()                      // IR: select(cond, discr!=0, false) — 순서 그대로 &&
{
    target_bush = self.target_bush.unwrap()            // self+0x8, 패닉 경로 없음(if-let 형태)
    return SubPlan::Hide(HideSubPlan{
        bush: target_bush,
        out_line: AroundBushOutlineType::Outline,      // 1
        check_move: false,                             // 0
        enemy_spotted_me: false,                       // 0
    })                                                 // tag 9
}

// L47 — 그 외: 에픽 사냥 돌입
return SubPlan::EpicHunt(EpicHuntSubPlan{ need_recall: false })   // tag 11, +0x8 에 i8 0
